---
interface Props {
  title: string;
  description: string;
  image?: string | undefined;
  canonicalPath?: string | undefined;
}
const {
  title,
  description,
  image,
  canonicalPath = Astro.url.pathname,
} = Astro.props;
const site = Astro.site ?? Astro.url;
const base = import.meta.env.BASE_URL.replace(/^\/+/, '');
const canonical = new URL(canonicalPath, site);
const imageUrl = image
  ? new URL(`${base}${image.replace(/^\//, '')}`, site)
  : undefined;
const feed = new URL(`${base}feed.xml`, site);
---

<title>{title}</title>
<meta name="description" content={description} />
<link rel="canonical" href={canonical} />
<link
  rel="alternate"
  type="application/rss+xml"
  title="Essentia card updates"
  href={feed}
/>
<meta property="og:type" content="website" />
<meta property="og:title" content={title} />
<meta property="og:description" content={description} />
<meta property="og:url" content={canonical} />
{imageUrl && <meta property="og:image" content={imageUrl} />}
{imageUrl && <meta property="og:image:alt" content={`${title} preview`} />}
<meta
  name="twitter:card"
  content={imageUrl ? 'summary_large_image' : 'summary'}
/>
<meta name="twitter:title" content={title} />
{imageUrl && <meta name="twitter:image" content={imageUrl} />}
{imageUrl && <meta name="twitter:image:alt" content={`${title} preview`} />}
<meta name="twitter:description" content={description} />

