from html.parser import HTMLParser
from pathlib import Path
import xml.etree.ElementTree as ET
class Audit(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True); self.stack=[]; self.title=[]; self.brands=[]; self.full=[]
    def handle_starttag(self, tag, attrs):
        d=dict(attrs); self.stack.append(tag)
        if tag=='a' and d.get('class') in ('brand','compact-brand'): self.brands.append(['',d])
    def handle_endtag(self, tag):
        if self.stack: self.stack.pop()
    def handle_data(self,data):
        if self.stack and self.stack[-1]=='title': self.title.append(data)
        if self.brands and self.stack and self.stack[-1]=='a': self.brands[-1][0]+=data
for f in sorted(Path('website/dist').rglob('*.html')):
    p=Audit(); text=f.read_text(); p.feed(text); p.close()
    print(f'{f.relative_to("website/dist")}: title={"".join(p.title)!r}; brands={[x[0] for x in p.brands]}; stale_full={"YGO × MTG" in text}')
r=ET.parse('website/dist/feed.xml').getroot()
