from pathlib import Path
import xml.etree.ElementTree as ET
class Audit(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True); self.title=[]; self.in_title=False; self.brand_depth=0; self.current=None; self.brands=[]
    def handle_starttag(self,tag,attrs):
        if tag=='title': self.in_title=True
        if self.current is not None: self.brand_depth += 1
        elif tag=='a' and dict(attrs).get('class') in ('brand','compact-brand'):
            self.current=''; self.brand_depth=1
    def handle_endtag(self,tag):
        if tag=='title': self.in_title=False
        if self.current is not None:
            self.brand_depth -= 1
            if self.brand_depth==0: self.brands.append(self.current.strip()); self.current=None
    def handle_data(self,data):
        if self.in_title: self.title.append(data)
        if self.current is not None: self.current += data
for f in sorted(Path('website/dist').rglob('*.html')):
